\[RSS + \lambda\left((1-\alpha)\sum_{i=1}^p\beta_j^2+\alpha\sum_{i=1}^p|\beta_j|\right)\]

ridge_spec &lt;- linear_reg(penalty = 100, mixture = 0) |&gt; 
